SELECT p.id AS position_id, e.delivery_status, e.outcome_reason, COUNT(*) AS n FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, e.delivery_status, e.outcome_reason ORDER BY p.id;
SELECT position_id, MAX(gap_ms) AS max_gap_ms FROM (SELECT p.id AS position_id, TIMESTAMPDIFF(MICROSECOND, LAG(e.observed_at) OVER (PARTITION BY p.id ORDER BY e.observed_at), e.observed_at)/1000 AS gap_ms FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (182,172,162,158,143,137)) g GROUP BY position_id ORDER BY position_id;